catch(Throwable $e) { http_response_code(503); exit('Model evidence is temporarily unavailable.'); }
$jobError=null; $activeJob=null;
try {
    if($_SERVER['REQUEST_METHOD']==='POST') {
        if($user['role']!=='admin') { http_response_code(403); throw new RuntimeException('Administrator access required.'); }
        requireCsrf(); limitRate('hardware:'.$user['id'],3,3600);
        $mode=(string)($_POST['mode']??'aer_noise');
        $parts=array_filter(array_map('trim',explode(',',(string)($_POST['review_ids']??''))));
        if(count($parts)<1||count($parts)>4||!in_array($mode,['aer_noise','ibm','ibm_with_fallback'],true)) throw new RuntimeException('Select one to four positive review IDs and a supported mode.');
        foreach($parts as $part) if(!ctype_digit($part)||(int)$part<1) throw new RuntimeException('Review IDs must be positive integers.');
        $job=modelJobRequest('/v1/score/batch',['review_ids'=>array_values(array_map('intval',$parts)),'mode'=>$mode,'async'=>true]);
        header('Location: /models.php?job='.rawurlencode($job['job_id']),true,303); exit;
    }
    if(isset($_GET['job'])) {
        if($user['role']!=='admin'||!preg_match('/^job_[a-f0-9]{32}$/D',(string)$_GET['job'])) { http_response_code(403); throw new RuntimeException('Administrator access and a valid job receipt are required.'); }
        $activeJob=modelJobRequest('/v1/jobs/'.$_GET['job']);
    }
} catch(Throwable $e) { $jobError=safeError($e); }
function artifact(string $name): ?array {
    $path=envv('MODEL_ARTIFACT_DIR',dirname(__DIR__).'/service/artifacts').'/'.$name;
    if(!is_file($path)||filesize($path)>5000000) return null;
    try { return json_decode(file_get_contents($path),true,64,JSON_THROW_ON_ERROR); } catch(Throwable $e) { return null; }
}
function metric(mixed $value): string { return is_numeric($value)?number_format((float)$value,3):'—'; }
